import com.spinplayer.app.*;import java.util.*;import java.util.concurrent.*;
public class LyricsSearchTest{public static void main(String[]args)throws Exception{ExecutorService pool=Executors.newFixedThreadPool(3);try{CountDownLatch began=new CountDownLatch(3);long start=System.nanoTime();LyricsProvider.Result r=LyricsSearch.run(Arrays.asList("slow","good","bad"),pool,s->{began.countDown();if(!began.await(1,TimeUnit.SECONDS))throw new AssertionError("sources serialized");if(s.equals("slow")){new CountDownLatch(1).await();}if(s.equals("bad"))throw new java.io.IOException();LyricsProvider.Result one=new LyricsProvider.Result();LyricsProvider.Candidate c=new LyricsProvider.Candidate();c.text="Original fixture";one.items.add(c);return one;},false,250);if(r.items.size()!=1||!"network_timeout".equals(r.statuses.get("slow"))||!"source_unavailable".equals(r.statuses.get("bad"))||(System.nanoTime()-start)>TimeUnit.SECONDS.toNanos(2))throw new AssertionError("timeout or result loss");CountDownLatch pending=new CountDownLatch(1);r=LyricsSearch.run(Arrays.asList("exact","slow"),pool,s->{LyricsProvider.Result one=new LyricsProvider.Result();if(s.equals("slow")){pending.countDown();new CountDownLatch(1).await();}else{pending.await(1,TimeUnit.SECONDS);LyricsProvider.Candidate c=new LyricsProvider.Candidate();c.confident=true;c.synced=true;one.items.add(c);}return one;},true,1000);if(r.items.size()!=1)throw new AssertionError("early exact result");System.out.println("PASS: concurrent sources, bounded wait, partial results, early exact result and cancellation");}finally{pool.shutdownNow();}}}
